<script setup>
import {reactive,ref,watch} from 'vue'
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app'
import VehicleList from '../../components/VehicleList.vue'
import QuestionConfirmation from '../../components/QuestionConfirmation.vue'
import QuestionRecovery from '../../components/QuestionRecovery.vue'
import {ownerSession} from '../../services/owner-session.js'
import {operatorSession,operatorToken} from '../../services/operator-session.js'
import {selectedOwnerVehicle,selectOwnerVehicle} from '../../services/owner-vehicle-selection.js'
import {createPublicImageApi,createPublicImageRecovery,publicImageRoute,PUBLIC_IMAGE_CONSENT} from '../../services/public-images.js'
import {createScopedIntentRecovery,intentUuid} from '../../services/scoped-intent-recovery.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {createQuestionConfirmation,pendingQuestion} from '../../services/community-question-recovery.js'
import {imageApi,imageRequestKey,MAX_IMAGE_BYTES} from '../../services/private-images.js'
import {TEXT_REASONS} from '../../services/public-review-texts.js'
const route=ref(null),reference=ref(''),source=ref(null),local=ref(null),copyId=ref(0),proposal=ref(null),consent=ref(false),seen=ref({}),pictures=ref({}),reasons=ref({})
const proposalViewed=ref(false)
const state=reactive(initialDiagnosisState()),uploadState=reactive(initialDiagnosisState()),confirmation=reactive({prompt:null}),prompt=ref(null),vehicle=selectedOwnerVehicle,api=createPublicImageApi()
const role=()=>route.value?.mode==='review'?'admin':'owner',token=()=>role()==='admin'?operatorToken():ownerSession.accessToken,actor=()=>role()==='admin'?operatorSession.actorId:ownerSession.actorId
const allowed=()=>Boolean(route.value&&(role()==='admin'?operatorSession.canReview:route.value.mode==='owner'||vehicle.value?.model_id))
const recovery=createPublicImageRecovery({actor,role,scope:()=>route.value?.mode==='review'?'review':'owner'}),gate=createQuestionConfirmation({state:confirmation,preview:()=>prompt.value})
async function load(t,p){
 if(route.value.mode==='review')return {applications:await api.pending(t,p)}
 if(route.value.mode==='public')return {public:await api.list(t,vehicle.value.vehicle_id,route.value.reference)}
 const applications=await api.own(t,p);let sources=null
 if(intentUuid(reference.value))try{sources=await api.sources(t,reference.value,p)}catch(e){if(['unauthorized','forbidden'].includes(e.kind))throw e;state.message='当前经验来源不可用，仍可管理本人历史申请'}
 return {applications,sources}
}
const recoveryAdapter={read:()=>route.value?.mode==='public'?{pending:null}:recovery.read(),savePending:v=>recovery.savePending(v),complete:v=>recovery.complete(v),clearPending:v=>recovery.clearPending(v),clear:()=>{if(route.value?.mode!=='public')recovery.clear()},marker:()=>recovery.marker(),discard:m=>recovery.discard(m)}
const flow=createAsyncDiagnosisFlow({state,token,allowed,scope:()=>`${role()}:${actor()}:${route.value?.mode}:${reference.value}:${vehicle.value?.vehicle_id}:${vehicle.value?.model_id}`,load,write:(t,a,id,b,k)=>api.write(t,a,id,b,k),newKey:imageRequestKey,recovery:recoveryAdapter,confirm:gate.ask,onWritten:clearForm})
const uploadRecovery=createScopedIntentRecovery({namespace:'public-image-upload',actor,role:()=> 'owner',scope:()=> 'upload',validate:(v,r,s)=>r==='owner'&&s==='upload'&&v.action==='upload'&&v.id===0&&Object.keys(v.body||{}).length===2&&typeof v.body.path==='string'&&v.body.path.length>0&&v.body.path.length<=2048&&Number.isSafeInteger(v.body.size)&&v.body.size>0&&v.body.size<=MAX_IMAGE_BYTES})
const uploadFlow=createAsyncDiagnosisFlow({state:uploadState,token,allowed:()=>route.value?.mode==='owner',scope:()=>`image-upload:${actor()}`,load:t=>api.own(t,1),write:(t,a,id,b,k)=>imageApi.upload(t,b,k),newKey:imageRequestKey,recovery:uploadRecovery,confirm:gate.ask,onWritten:result=>{copyId.value=result.file_id;local.value=null;proposal.value=null;proposalViewed.value=false;consent.value=false}})
let visible=false,epoch=0
const blocked=()=>state.busy||state.retry||state.kind==='storage'||uploadState.busy||uploadState.retry||uploadState.kind==='storage'
function clearForm(){epoch++;source.value=null;local.value=null;copyId.value=0;proposal.value=null;proposalViewed.value=false;consent.value=false;prompt.value=null;seen.value={};pictures.value={};reasons.value={}}
function reset(){gate.cancel();flow.reset();uploadFlow.reset();clearForm()}
function refresh(){if(blocked())return;clearForm();flow.load(state.page);if(route.value?.mode==='owner')uploadFlow.load()}
function useReference(){if(blocked())return;const value=reference.value.trim();if(!intentUuid(value)){state.message='请输入本人已获批经验的公开UUID';return}reference.value=value;clearForm();flow.load();uploadFlow.load()}
function select(row){if(blocked())return;source.value=row;proposal.value=null;proposalViewed.value=false;consent.value=false}
async function original(row){const e=epoch,t=token();try{const access=await imageApi.access(t,row.source_file_id);if(visible&&e===epoch&&token()===t)await imageApi.preview(access.url)}catch(err){if(visible&&e===epoch)state.message=err.message}}
async function choose(){if(blocked())return;const e=epoch,t=token();try{const file=await imageApi.choose(t);if(visible&&e===epoch&&token()===t&&file){local.value=file;copyId.value=0;proposal.value=null;proposalViewed.value=false;consent.value=false}}catch(err){if(visible&&e===epoch)state.message=err.message}}
function upload(){if(blocked()||!local.value)return;prompt.value={title:'确认上传独立脱敏副本',lines:['请事先遮挡车牌、VIN、人脸、电话、地址和其他个人信息；此操作只上传私有副本，不公开。',`本机文件 ${local.value.path} · ${local.value.size} 字节`,'上传失败或响应未知时，用本机已保存的同文件同键恢复。']};uploadFlow.save('upload',0,{path:local.value.path,size:local.value.size})}
async function preview(){if(blocked()||!source.value||!copyId.value)return;const e=++epoch,t=token();state.busy=true;proposal.value=null;proposalViewed.value=false;consent.value=false;const b={experience_id:reference.value,archive_id:source.value.archive_id,source_file_id:source.value.source_file_id,copy_file_id:copyId.value};try{const result=await api.preview(t,b);if(visible&&e===epoch&&token()===t)proposal.value={...result,selection:b}}catch(err){if(visible&&e===epoch){state.message=err.message;state.kind=err.kind||'server'}}finally{if(e===epoch)state.busy=false}}
function submit(){if(blocked()||!proposal.value||!consent.value||!proposalViewed.value)return;prompt.value={title:'确认逐张公开本次副本',lines:[`车型 ${proposal.value.model_id} · ${proposal.value.width}×${proposal.value.height}`,`父经验 ${proposal.value.selection.experience_id}`,'请核对屏幕中的副本；只提交这一张重新编码的PNG供人工审核和同款展示，不公开原图。',`预览 ${proposal.value.preview_hash} · 授权 ${PUBLIC_IMAGE_CONSENT}`]};flow.save('submit',0,{...proposal.value.selection,preview_hash:proposal.value.preview_hash,consent_version:PUBLIC_IMAGE_CONSENT,consent:true})}
async function view(row){if(blocked())return;const e=epoch,t=token(),publicMode=route.value.mode==='public';try{const value=publicMode?await api.bytes(t,vehicle.value.vehicle_id,row.public_id):await api.previewBytes(t,role(),row.application_id);if(visible&&e===epoch&&token()===t){const id=publicMode?row.public_id:row.application_id;pictures.value={...pictures.value,[id]:'data:image/png;base64,'+value.png_base64};seen.value={...seen.value,[id]:null}}}catch(err){if(e===epoch){pictures.value={};seen.value={};state.message=err.message;state.kind=err.kind||'server'}}}
function act(row,decision){if(blocked()||!state.data?.applications.items.includes(row))return;const review=route.value.mode==='review',reason=decision==='REJECT'?reasons.value[row.application_id]:null;if(review&&(decision==='APPROVE'&&(!row.source_available||seen.value[row.application_id]!==row.preview_hash)||decision==='REJECT'&&!Object.hasOwn(TEXT_REASONS,reason))){state.message='批准前须加载并实际核对本次副本；驳回须选择原因';return}if(!review&&row.status==='WITHDRAWN')return;prompt.value={title:review?'确认图片人工审核':'确认撤回本张图片',lines:[`申请 ${row.application_id} · 版本 ${row.revision} · 预览 ${row.preview_hash}`,`父经验 ${row.experience_id}`,review?(decision==='APPROVE'?'已实际检查副本无隐私，并核对授权及来源':TEXT_REASONS[reason]):'立即拒绝后续读取；已下载/截图的内容不能远程收回。']};flow.save(review?'moderate':'withdraw',row.application_id,review?{expected_revision:row.revision,decision,reason_code:reason}:{expected_revision:row.revision})}
function page(delta){if(blocked()||state.page+delta<1)return;clearForm();flow.load(state.page+delta)}
function login(){uni.navigateTo({url:role()==='admin'?'/pages/operator/login':'/pages/owner/index'})}
watch(()=>[token(),actor(),allowed(),vehicle.value?.vehicle_id,vehicle.value?.model_id],()=>{reset();if(visible&&token()&&allowed()){flow.load();if(route.value?.mode==='owner')uploadFlow.load()}},{flush:'sync'})
watch(reference,()=>{reset()},{flush:'sync'})
onLoad(q=>{route.value=publicImageRoute(q||{});reference.value=route.value?.reference||''});onShow(()=>{visible=true;if(token()&&allowed()){flow.load();if(route.value?.mode==='owner')uploadFlow.load()}})
function hide(){visible=false;reset()}onHide(hide);onUnload(hide)
</script>
<template><view class="reservation-page"><text class="reservation-title">{{route?.mode==='review'?'脱敏副本逐张审核':route?.mode==='public'?'同款已授权图片':'我的图片公开授权'}}</text><text>系统重新编码去除元数据；视觉隐私须由车主遮挡并由人工审核。原图保持私有。</text><text v-if="!route">入口参数无效</text><button v-if="!token()" @tap="login">登录当前身份</button><text v-if="route?.mode==='review'&&!allowed()">需要内容审核权限</text><VehicleList v-if="route?.mode==='public'" :selected-id="vehicle?.vehicle_id||0" @select="selectOwnerVehicle"/>
 <QuestionRecovery v-if="route&&route.mode!=='public'" :state="state" :flow="flow" :pending="pendingQuestion(recovery)"/><QuestionRecovery v-if="route?.mode==='owner'" :state="uploadState" :flow="uploadFlow" :pending="pendingQuestion(uploadRecovery)"/>
 <text v-if="route?.mode==='public'&&state.message" role="status">{{state.message}}</text><button :disabled="blocked()||!token()||!allowed()" @tap="refresh">刷新当前来源与申请</button>
 <view v-if="route?.mode==='owner'&&token()&&state.data" class="reservation-panel"><input v-model="reference" maxlength="36" :disabled="blocked()" placeholder="本人已获批经验的公开UUID"/><button :disabled="blocked()" @tap="useReference">核验父经验并选择原图</button><view v-for="row in state.data?.sources?.items||[]" :key="row.source_file_id"><text>档案 {{row.archive_id}} · 图片 {{row.source_file_id}}</text><button :disabled="blocked()" @tap="original(row)">私下查看原图</button><button :disabled="blocked()" @tap="select(row)">{{source?.source_file_id===row.source_file_id?'已选择':'选择此图'}}</button></view><button :disabled="blocked()" @tap="choose">选择已遮挡隐私的独立副本</button><text v-if="local">已选择 {{local.size}} 字节副本</text><button :disabled="blocked()||!local" @tap="upload">确认并上传私有副本</button><text v-if="copyId">副本上传成功：{{copyId}}（仍未公开）</text><button :disabled="blocked()||!source||!copyId" @tap="preview">服务器生成去元数据预览</button><view v-if="proposal"><image :src="'data:image/png;base64,'+proposal.png_base64" mode="widthFix" @load="proposalViewed=true" @error="proposalViewed=false"/><checkbox-group @change="consent=$event.detail.value.includes('yes')"><label><checkbox value="yes" :checked="consent" :disabled="blocked()||!proposalViewed"/>已查看副本并逐图同意公开用途</label></checkbox-group><button :disabled="blocked()||!consent||!proposalViewed" @tap="submit">完整确认并申请公开本张</button></view></view>
 <view v-for="row in state.data?.applications?.items||[]" :key="row.application_id" class="reservation-panel"><text>申请 {{row.application_id}} · {{row.status}} · 版本 {{row.revision}}</text><text>车型 {{row.model_id}} · {{row.width}}×{{row.height}} · {{row.source_available?'来源当前有效':'来源当前不可用'}}</text><button :disabled="blocked()" @tap="view(row)">核验并查看本次脱敏副本</button><image v-if="pictures[row.application_id]" :src="pictures[row.application_id]" mode="widthFix" @load="seen[row.application_id]=row.preview_hash" @error="seen[row.application_id]=null"/><template v-if="route.mode==='review'"><button :disabled="blocked()||!row.source_available||seen[row.application_id]!==row.preview_hash" @tap="act(row,'APPROVE')">预览批准</button><picker :range="Object.values(TEXT_REASONS)" @change="reasons[row.application_id]=Object.keys(TEXT_REASONS)[Number($event.detail.value)]"><view>驳回原因：{{TEXT_REASONS[reasons[row.application_id]]||'请选择'}}</view></picker><button :disabled="blocked()" @tap="act(row,'REJECT')">预览驳回</button></template><button v-else-if="row.status!=='WITHDRAWN'" :disabled="blocked()" @tap="act(row,'WITHDRAW')">预览撤回本张</button></view>
 <view v-for="row in state.data?.public?.items||[]" :key="row.public_id" class="reservation-panel"><text>已授权审核 · {{row.published_at}}</text><button :disabled="blocked()" @tap="view(row)">重新核验并加载图片</button><image v-if="pictures[row.public_id]" :src="pictures[row.public_id]" mode="widthFix"/></view><text v-if="state.data?.public&&!state.data.public.items.length">当前无可展示图片</text>
 <button v-if="state.page>1" :disabled="blocked()" @tap="page(-1)">上一页</button><button v-if="state.page*20<(state.data?.applications?.total||0)||state.page*20<(state.data?.sources?.total||0)" :disabled="blocked()" @tap="page(1)">下一页</button><QuestionConfirmation :prompt="confirmation.prompt" @answer="gate.settle"/></view></template>
<style scoped>image{width:100%;max-width:640px}</style>
